# Common cross-compile environment for aarch64 (Tizen target)
export THIRDPARTY_DIR="/home/user/tizenroblox/thirdparty"
export SRC_DIR="${THIRDPARTY_DIR}/src"
export PREFIX="${THIRDPARTY_DIR}/install"
export CROSS_PREFIX="aarch64-linux-gnu"
export CC="${CROSS_PREFIX}-gcc"
export CXX="${CROSS_PREFIX}-g++"
export AR="${CROSS_PREFIX}-ar"
export RANLIB="${CROSS_PREFIX}-ranlib"
export STRIP="${CROSS_PREFIX}-strip"
export LD="${CROSS_PREFIX}-ld"
export HOST="aarch64-linux-gnu"
export PKG_CONFIG_PATH="${PREFIX}/lib/pkgconfig"
export PKG_CONFIG_LIBDIR="${PREFIX}/lib/pkgconfig"
export PKG_CONFIG_SYSROOT_DIR=""
export CFLAGS="-O2 -fPIC -I${PREFIX}/include"
export LDFLAGS="-L${PREFIX}/lib"
mkdir -p "${SRC_DIR}" "${PREFIX}"
